// #f0f6e2 (aeb6b4a4d630df5aa3f0f6e2) — меню действий строки «⋮», открытое на 1440, оставалось за экраном после сужения окна.
// Проверка (как 21.10): открыть меню на 1440×700 → окно 250×700 → меню закрыто, ни одной кнопки с aria-expanded="true".
// Три места: строка приглашения и строка пользователя в /settings/users (business), строка /admin/support (admin).
// Кейсы ROWMENU-001…003. Только чтение (меню открывается, пункты не нажимаются) → @prod-safe. Админка — только десктоп (L-20261014-5).
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

const HASH = '#f0f6e2 · #aeb6b4a4d630df5aa3f0f6e2';

const PLACES = [
  { name: 'строка приглашения /settings/users', user: 'business', url: '/settings/users', button: /^פעולות עבור ההזמנה של / },
  { name: 'строка пользователя /settings/users', user: 'business', url: '/settings/users', button: /^פעולות עבור (?!ההזמנה של )/ },
  { name: 'строка /admin/support', user: 'admin', url: '/admin/support', button: /^פעולות/ },
] as const;

/** Открытое меню строки (закрытое скрывается атрибутом hidden или удаляется). */
const openMenu = (page: Page) => page.locator('[role="menu"]:not([hidden])');

test.describe(`Меню строки закрывается при сужении окна 1440 → 250 (${HASH})`, () => {
  for (const place of PLACES) {
    test(`${place.name}: после 1440→250 меню закрыто, aria-expanded="true" не осталось @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const page = await asUser(place.user);
      await page.setViewportSize({ width: 1440, height: 700 });
      await page.goto(place.url);

      const button = page.getByRole('button', { name: place.button }).first();
      await expect(button, `нет кнопки меню (${place.name}) — нужны QA-данные: приглашение/пользователь/строка поддержки`).toBeVisible({ timeout: 30_000 });
      await button.scrollIntoViewIfNeeded();
      await button.click();
      await expect(openMenu(page)).toBeVisible();
      await expect(button).toHaveAttribute('aria-expanded', 'true');

      await page.setViewportSize({ width: 250, height: 700 });

      // Источник: «מה רצוי» #f0f6e2 — при смене ширины меню не остаётся за экраном: закрывается и кнопка не «раскрыта».
      await expect(openMenu(page), 'меню осталось открытым после 1440→250').toBeHidden();
      await expect(page.locator('button[aria-expanded="true"]'), 'кнопка осталась aria-expanded="true"').toHaveCount(0);
    });
  }
});
